parameters.jsonBody:
={
  "model": "google/gemini-3-pro-preview",
  "response_format": { "type": "json_object" },
  "temperature": 0.7,
  "messages": [
    {
      "role": "system",
      "content": "Eres un copywriter experto en cold outreach B2B en español. Tu tarea es generar un correo de prospección altamente personalizado y una propuesta comercial breve. Responde SIEMPRE en JSON válido con las claves: subject, email_body, proposal_title, proposal_text. Reglas: (1) Usa tono cercano y consultivo, no genérico. (2) Menciona algo específico de la empresa del lead. (3) Ofrece tres líneas de servicio: contenido viral con calendarios y planificación, landing pages que maximizan ventas, y automatización de procesos. (4) El CTA del email debe ser explícitamente agendar una reunión usando el enlace proporcionado. (5) email_body en HTML simple (<p>, <strong>, <ul>) listo para Gmail. (6) proposal_text de máximo 180 palabras, directo y orientado a resultados."
    },
    {
      "role": "user",
      "content": "Genera el correo y la propuesta para este lead:\n\nNombre: {{$json.fullName}}\nCargo: {{$json.title}}\nEmpresa: {{$json.companyName}}\nIndustria: {{$json.companyIndustry}}\nDescripción: {{$json.companyDescription}}\nDominio: {{$json.companyDomain}}\n\nRemitente: {{$('Set Campaign Vars').item.json.senderName}} de {{$('Set Campaign Vars').item.json.senderCompany}}\nEnlace para agendar: {{$('Set Campaign Vars').item.json.calendarLink}}"
    }
  ]
}

parameters.jsCode:
const lead = $('Normalize Lead').item.json;
const raw = $input.item.json.choices?.[0]?.message?.content || '{}';

let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  ai = match ? JSON.parse(match[0]) : {};
}

const subject       = ai.subject       || `Propuesta para ${lead.companyName}`;
const emailBody     = ai.email_body    || '';
const proposalTitle = ai.proposal_title || `Propuesta para ${lead.companyName}`;
const proposalText  = ai.proposal_text  || '';

const sender = $('Set Campaign Vars').item.json;
const today = new Date().toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' });

const escape = (s = '') => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const proposalHtml = `<!doctype html><html><head><meta charset="utf-8"><title>${escape(proposalTitle)}</title>
<style>
  body{font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a1a;margin:48px;line-height:1.55;}
  .header{border-bottom:3px solid #4F46E5;padding-bottom:16px;margin-bottom:32px;}
  h1{margin:0 0 8px 0;font-size:26px;color:#4F46E5;}
  .meta{color:#666;font-size:13px;}
  .section{margin:24px 0;}
  .pillars{display:block;margin:24px 0;}
  .pillar{padding:14px 18px;border-left:4px solid #4F46E5;background:#F5F3FF;margin-bottom:12px;}
  .cta{margin-top:32px;padding:20px;background:#111;color:#fff;border-radius:8px;text-align:center;}
  .cta a{color:#fff;text-decoration:none;font-weight:bold;}
  .footer{margin-top:40px;font-size:12px;color:#888;border-top:1px solid #eee;padding-top:12px;}
</style></head><body>
  <div class="header">
    <h1>${escape(proposalTitle)}</h1>
    <div class="meta">Para: ${escape(lead.fullName)} — ${escape(lead.companyName)} · ${escape(today)}</div>
  </div>
  <div class="section">${escape(proposalText).replace(/\n/g,'<br>')}</div>
  <div class="pillars">
    <div class="pillar"><strong>Contenido viral</strong> — calendarios y planificación para captar clientes.</div>
    <div class="pillar"><strong>Landing pages</strong> — diseño orientado a conversión para maximizar ventas.</div>
    <div class="pillar"><strong>Automatización</strong> — flujos que liberan horas de tu equipo cada semana.</div>
  </div>
  <div class="cta">¿Lo vemos en una llamada de 30 min? <a href="${escape(sender.calendarLink)}">Agendar reunión</a></div>
  <div class="footer">${escape(sender.senderName)} — ${escape(sender.senderCompany)}</div>
</body></html>`;

return [{ json: { subject, emailBody, proposalTitle, proposalText, proposalHtml, lead, sender } }];
